    followupTokens: integer(input.followupTokens, d.followupTokens, 256, 16384, '追问回复上限'),
    contextDepth: integer(input.contextDepth, d.contextDepth, -1, 500, '最近剧情条数'),
    historyTurns: integer(input.historyTurns, d.historyTurns, 0, 30, '追问历史轮数'),
