    const away = `translate(${helperId === 'ketchup' ? -stage.clientWidth * .85 : stage.clientWidth * .65}px, ${-stage.clientHeight * .38}px) rotate(${helperId === 'ketchup' ? -12 : 12}deg)`;
    const outgoing = await travel([{ transform: 'translate(0,0) rotate(0)', opacity: 1 }, { transform: away, opacity: 0 }], 430);
    if (!active()) return;
    setPhase('helper-away');
    await delay(1600);
    if (!active()) return;
    button.querySelector('.helper-reward').hidden = true;
    image.src = sources[resting]; image.dataset.art = resting;
    setPhase('helper-returning');
