modules["standalone/christina-tarot-room/core/character-context.js"] = (() => {
const { TAROT_CHARACTER_CATALOG } = modules["standalone/christina-tarot-room/core/character-catalog.js"];

function containsAlias(text, alias) {
  if (!/^[a-z0-9_-]+$/i.test(alias)) return text.includes(alias);
  const escaped = alias.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`(^|[^a-z0-9_])${escaped}(?=$|[^a-z0-9_])`, 'i').test(text);
}

/** Search the selected question/story/history, never other reference cards or the whole host persona. */
function selectCharacterReferences({ record, host, context, previous = [], reading = null, question = '' }) {
  const corpus = JSON.stringify({ question: record.question, labels: record.labels, followup: question,
    context, previous, reading, opening: host.opening?.(record.snapshot.presence) || '' });
  return TAROT_CHARACTER_CATALOG.filter(character => character.id !== host.id && character.aliases.some(alias => containsAlias(corpus, alias)))
    .map(character => ({ id: character.id, name: character.displayName, trueName: character.trueName,
      ...(character.title ? { title: character.title } : {}), setting: character.brief,
      ...(typeof host.characterKnowledge?.[character.id] === 'string' && host.characterKnowledge[character.id].trim()
        ? { hostKnowledge: host.characterKnowledge[character.id].trim() } : {}),
    }));
}

return { selectCharacterReferences: selectCharacterReferences };
})();
