    footer('<span class="small">交谈与牌局保存在各自的旅途中。</span>', action('export', '导出手记') + action('archive', '过去的指引') + action('open-history', '翻开这一页', true, dis(!vm?.state?.records.length || busy())));
    renderHistory();
