    overlay.hidden = true;
    overlay.style.cssText = 'position:fixed;inset:0;z-index:2147483005;display:none;flex-direction:column;background:#28372d;color:#efe1c4';
    const bar = document.createElement('div');
    bar.style.cssText = 'display:flex;align-items:center;justify-content:space-between;padding:6px 12px;gap:12px;background:#26352d;font:14px/1.5 sans-serif';
    const label = document.createElement('span'); label.textContent = ENTRY_OPTIONS.title;
    closeButton = document.createElement('button'); closeButton.type = 'button'; closeButton.textContent = '返回酒馆';
    closeButton.style.cssText = button.style.cssText;
    closeButton.addEventListener('click', hide); bar.append(label, closeButton);
    frame = document.createElement('iframe'); frame.title = ENTRY_OPTIONS.title;
    frame.style.cssText = 'display:block;flex:1;min-height:0;width:100%;border:0;background:#28372d';
