      shellRecovery.style.cssText = 'position:absolute;inset:48px 0 0;padding:15vh 24px 24px;background:#28372d;text-align:center';
      shellStatus = document.createElement('p'); shellStatus.setAttribute('role','status');
      const retry = document.createElement('button'); retry.textContent = '重新打开网页'; retry.style.cssText = button.style.cssText;
      const fallback = document.createElement('button'); fallback.textContent = '使用内置界面'; fallback.style.cssText = button.style.cssText;
      retry.addEventListener('click', () => {
        closeConnection(); frame.removeEventListener('load',onFrameLoad); closeButton.removeEventListener('click',hide);
        overlay.remove(); overlay = null; frame = null; shellRecovery = null; shellStatus = null;
        open();
      });
      fallback.addEventListener('click', () => { hide(); closeConnection(); hostWindow.__TRUE_KING_V2__?.open?.(); });
