      if (typeof tavern?.getContext !== 'function') throw new Error('未找到当前酒馆上下文。页面保持未连接，不会读写 FP。');
      reader = createTavernContextReader({ getContext: tavern.getContext.bind(tavern) });
      reader.getContext();
      adapter = createExistingCoreAdapter({ hostWindow, getContext: () => reader.getContext() });
