      if(ready){const button=document.createElement('button');button.type='button';button.textContent=delivered?(letter.read?'再次阅读':'拆信阅读'):'接过这封信';
        button.addEventListener('click',()=>run(async()=>{if(!delivered)return harness.receive(letter.id);const value=await harness.read(letter.id);reading.textContent=(value.title||'来信')+'\n'+(value.senderName||value.senderId||'')+'\n\n'+value.body;reading.hidden=false;}));box.append(button);}
