  shadow.querySelector('.close').addEventListener('click',close);veil.addEventListener('click',event=>{if(event.target===veil)close();});hostWindow.addEventListener('keydown',onKey,true);
  shadow.querySelector('[data-action="refresh"]').addEventListener('click',()=>run(()=>harness.check('auto')));
  shadow.querySelector('[data-action="check"]').addEventListener('click',()=>run(()=>harness.check('manual')));
  calendar.addEventListener('change',()=>run(async()=>{await harness.setCalendar(calendar.value);await harness.check('auto');}));
  // Installed alongside the core once, independently of whether its panel is open.
  try {
    harness=createMailTestHarness({domain:mailDomain,flowApi:mailFlowApi,storeKey:'livia_mail_core_v1',promptId:'true-king-livia-mail-mainline',queryTrigger:true,onPresent:present,access:{
      getContext,getVariables:resolve('getVariables'),updateVariablesWith:resolve('updateVariablesWith'),getChatMessages:resolve('getChatMessages'),eventOn:resolve('eventOn'),events:resolve('tavern_events'),injectPrompts:resolve('injectPrompts'),uninjectPrompts:resolve('uninjectPrompts'),
      isGenerating:()=>generationReader?.()??null,readPendingUserInput:()=>document.getElementById('send_textarea')?.value||'',
    }});
    hostWindow.__LIVIA_MAIL_PROTOTYPE_CLEANUP__?.();hostWindow.__LIVIA_CORE_FIELDTEST_CLEANUP__?.();harness.bind();
    void run(async()=>{try{const url=new URL('./script.js',document.baseURI);const module=await hostWindow.Function('url','return import(url)')(url.href);if(typeof module.isGenerating==='function')generationReader=()=>module.isGenerating();}catch{}await harness.check('auto');});
  }catch(error){present({error:error.message});}
  render();
  return { async open(){veil.hidden=false;shadow.querySelector('.close').focus();if(harness)await run(()=>harness.check('auto'));},
    getStatus(){return {badge:items().filter(x=>!x.read&&(x.status==='sealed'||x.status==='delivered'||x.delivered)).length};},
    destroy(){disposed=true;harness?.destroy();hostWindow.removeEventListener('keydown',onKey,true);root.remove();},
  };
