    if(/^[\x00-\x7f]+$/.test(alias)){const escaped=alias.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/\s+/g,'\\s*');return new RegExp('\\b'+escaped+'\\b','i').test(text);}
    return text.includes(alias)&&!(alias==='基督'&&/基督教|基督徒|反基督/.test(text));
