  let model=null,selected=null,mode='roam',category='全部',detailTab='description',quantity=1,busy=false,disposed=false,abort=null,operation=null,returnFocus=null,onReturn=null,restoreApi=null,notice='',error=false,favorites=false,activeRules=null,activeCharacterRules=null,characterRuleError='',guideItem=null,guideChannel='surface';
