  function status(){ $('.ls-restock').disabled=busy;$('.ls-restock').innerHTML=busy?'正在穿越诸界…':'请她去进货 <small>免费</small>';$('.ls-wallet strong').textContent=model?money(model.balance)+' FP':'— FP';panel.classList.toggle('is-busy',busy);input.disabled=busy;for(const node of shadow.querySelectorAll('[data-mode],.ls-favorite,.ls-buy'))node.disabled=busy; }
