    input.placeholder=mode==='world'?'输入任意动漫、小说或游戏作品':mode==='need'?'例如：恢复体力的消耗品、某位神明本体':'搜索当前货架；也可留下进货偏好';
    const worldList=$('datalist');worldList.replaceChildren();for(const name of [...new Set([...policy.worlds,...(model?.ledger.worlds||[])])]){const option=el('option');option.value=name;worldList.append(option);}
