    const shown=list.filter(x=>(category==='全部'||x.category===category)&&(!needle||[x.name,x.source,x.edition].join(' ').toLowerCase().includes(needle)));
    const shelf=$('.ls-shelf'),special=$('.ls-special');shelf.replaceChildren();special.replaceChildren();
