    if(!item){detail.append(el('div','✧','ls-detail-mark'),el('h2','您的选品单'),el('p','点选一件商品，在这里查看出处、效果与交付方式。','ls-intro'));return;}
    detail.append(imageFor(item,item.special),el('h2',item.name),el('p',item.source+' · '+item.edition,'ls-source'),el('p',item.tier+' / '+item.category+' / '+item.delivery,'ls-delivery'));
    const tabs=el('nav',undefined,'ls-detail-tabs');for(const [id,label]of [['description','商品说明'],['recommendation','利维娅推荐']]){const b=button(label,()=>{detailTab=id;if(id==='recommendation')showSelected();renderDetail();});b.setAttribute('aria-pressed',String(detailTab===id));tabs.append(b);}detail.append(tabs);
