    const fav=button(isFavorite(item)?'♥ 已收藏 · 取消收藏':'♡ 收藏这件好物',()=>run(async()=>{apply(await host.mutate(model.token,(vars,ledger)=>{if(ledger.favorites.some(x=>x.id===item.id))ledger.favorites=ledger.favorites.filter(x=>x.id!==item.id);else ledger.favorites.push(shopCopy(item));ledger.revision++;return ledger;}));setNotice(isFavorite(item)?'已经替您留下，换一批货也能回来购买。':'已取消收藏。');}),'ls-favorite');fav.disabled=busy;detail.append(fav);
